def before_insert(doc, method=None):
    # Try different possible params
    job_from_url = frappe.form_dict.get("job") or frappe.form_dict.get("job_title")

    if job_from_url:
        doc.job_title = job_from_url
    else:
        # fallback: pick first open job
        default_job = frappe.db.get_value("Job Opening", {"status": "Open"}, "name")
        if default_job:
            doc.job_opening = default_job

if doc.email:
    usersetting = frappe.get_doc({
        "doctype": "User Setting",
        "user":doc.email
    })
    usersetting.insert()

# update custom_assigned_to_ with first assigned user
assigned_users = frappe.get_all(
    "ToDo",
    filters={
        "reference_type": "Opportunity",
        "reference_name": doc.name,
        "status": "Open"
    },
    fields=["allocated_to"],
    limit=1
)

if assigned_users:
    doc.db_set("custom_assigned_to_", assigned_users[0].allocated_to)

# Server Script for Staffing Plan
# Document Events: After Save
# Document Type: Staffing Plan

# Existing functionality - Assign entire Staffing Plan to one user
if doc.custom_assign_to:
    # Check if ToDo already exists to avoid duplicates
    existing_todo = frappe.db.exists("ToDo", {
        "reference_type": "Staffing Plan",
        "reference_name": doc.name,
        "allocated_to": doc.custom_assign_to,
        "status": ["!=", "Cancelled"]
    })
    
    if not existing_todo:
        try:
            # Create new ToDo with required fields
            todo = frappe.get_doc({
                "doctype": "ToDo",
                "allocated_to": doc.custom_assign_to,
                "reference_type": "Staffing Plan",
                "reference_name": doc.name,
                "description": f"Review and work on Staffing Plan: {doc.name} for Company: {doc.company or 'N/A'}",
                "priority": "Medium",
                "status": "Open",
                "date": doc.from_date or frappe.utils.today(),
                "assigned_by": frappe.session.user
            })
            
            # Insert the ToDo
            todo.insert(ignore_permissions=True)
            
            frappe.msgprint(f"ToDo created for user: {doc.custom_assign_to}")
            
        except Exception as e:
            frappe.log_error(f"Error creating ToDo for Staffing Plan {doc.name}: {str(e)}")
            frappe.throw(f"Failed to create ToDo: {str(e)}")

# New functionality - Assign individual rows to different users with position allocation
assigned_users = []
total_allocated_positions = 0

for row in doc.staffing_details:
    if row.assign_to:  # Only process rows that have assigned users
        # Split comma-separated user allocations
        user_allocations = [allocation.strip() for allocation in row.assign_to.split(',') if allocation.strip()]
        
        row_allocated_positions = 0
        valid_allocations = []
        
        for user_allocation in user_allocations:
            # Parse user-positions format: email-10 or just email
            if '-' in user_allocation:
                try:
                    parts = user_allocation.rsplit('-', 1)  # Split from right to handle emails with dashes
                    user_email = parts[0].strip()
                    positions_str = parts[1].strip()
                    allocated_positions = int(positions_str)
                except (ValueError, IndexError):
                    frappe.msgprint(f"Invalid format '{user_allocation}' in Row {row.idx}. Use format: email-positions", indicator='orange')
                    continue
            else:
                # Fallback: if no positions specified, distribute equally among all users
                user_email = user_allocation.strip()
                total_users = len([u for u in user_allocations if '-' not in u])
                if total_users > 0:
                    allocated_positions = (row.number_of_positions or 0) // len(user_allocations)
                else:
                    allocated_positions = 0
            
            # Validate if user exists
            if not frappe.db.exists("User", user_email):
                frappe.msgprint(f"User {user_email} not found in Row {row.idx}. Skipping.", indicator='orange')
                continue
            
            valid_allocations.append({
                'user_email': user_email,
                'allocated_positions': allocated_positions
            })
            row_allocated_positions += allocated_positions
        
        # Validate total allocation doesn't exceed available positions
        if row_allocated_positions > (row.number_of_positions or 0):
            frappe.msgprint(f"Row {row.idx}: Total allocated positions ({row_allocated_positions}) exceeds available positions ({row.number_of_positions or 0})", indicator='orange')
        
        # Create ToDos for valid allocations
        for allocation in valid_allocations:
            user_email = allocation['user_email']
            allocated_positions = allocation['allocated_positions']
            
            # Check if ToDo already exists for this specific row and user
            existing_todo = frappe.db.exists("ToDo", {
                "reference_type": "Staffing Plan",
                "reference_name": doc.name,
                "allocated_to": user_email,
                "description": ["like", f"%Row {row.idx}%"],
                "status": ["!=", "Cancelled"]
            })
            
            if not existing_todo:
                try:
                    # Build detailed description for this specific row and allocation
                    description = f"""
Staffing Plan Assignment - Row {row.idx}
Staffing Plan: {doc.name}
Company: {doc.company or 'N/A'}
Department: {doc.department or 'N/A'}
Plan Duration: {doc.from_date or 'N/A'} to {doc.to_date or 'N/A'}

Position Details:
• Designation: {row.designation or 'N/A'}
• YOUR ALLOCATED POSITIONS: {allocated_positions}
• Total Positions in This Row: {row.number_of_positions or 0}
• Vacancies: {row.vacancies or 0}
• Current Count: {row.current_count or 0}
• Current Openings: {row.current_openings or 0}
• Cost Per Position: {frappe.format_value(row.estimated_cost_per_position, 'Currency'+ "LPA") if row.estimated_cost_per_position else 'N/A'}
• Your Target Cost: {frappe.format_value((row.estimated_cost_per_position or 0) * allocated_positions, 'Currency') + "LPA"}
• Min Experience Required: {row.min_experience_req or 0} years
• Min Experience Required: {row.location}
• Job Description: {frappe.utils.strip_html(row.job_description) if row.job_description else 'N/A'}

All Assignments for This Position: {row.assign_to}
                    """.strip()
                    
                    # Create new ToDo for this specific row and user
                    todo = frappe.get_doc({
                        "doctype": "ToDo",
                        "allocated_to": user_email,
                        "reference_type": "Staffing Plan",
                        "reference_name": doc.name,
                        "description": description,
                        "custom_job_id":row.job_id,
                        "priority": "Medium",
                        "status": "Open",
                        "date": doc.from_date or frappe.utils.today(),
                        "assigned_by": frappe.session.user
                    })
                    
                    # Insert the ToDo
                    todo.insert(ignore_permissions=True)
                    
                    assigned_users.append(f"{user_email} ({allocated_positions} positions)")
                    total_allocated_positions += allocated_positions
                    
                except Exception as e:
                    frappe.log_error(f"Error creating ToDo for Staffing Plan {doc.name}, Row {row.idx}, User {user_email}: {str(e)}")
                    frappe.msgprint(f"Failed to create ToDo for row {row.idx}, user {user_email}: {str(e)}", indicator='red')
            else:
                frappe.msgprint(f"ToDo already exists for {user_email} in Row {row.idx}", indicator='blue')

# Show success message for individual assignments
if assigned_users:
    unique_users = len(set([user.split(' (')[0] for user in assigned_users]))
    frappe.msgprint(f"Individual ToDos created:<br>• Total: {len(assigned_users)} assignments<br>• Users: {unique_users}<br>• Total Positions Allocated: {total_allocated_positions}<br>• Details: {', '.join(assigned_users[:5])}{'...' if len(assigned_users) > 5 else ''}", indicator='green')
